<template><div><h1 id="phalcon" tabindex="-1"><a class="header-anchor" href="#phalcon" aria-hidden="true">#</a> Phalcon</h1>
<h2 id="querybuilder-usage" tabindex="-1"><a class="header-anchor" href="#querybuilder-usage" aria-hidden="true">#</a> QueryBuilder usage</h2>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token variable">$qb</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token property">modelsManager</span><span class="token operator">-></span><span class="token function">createBuilder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token operator">-></span><span class="token function">addFrom</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'CompanySite'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'cs'</span><span class="token punctuation">)</span>
        <span class="token operator">-></span><span class="token function">columns</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
            <span class="token string single-quoted-string">'cp.id as company_id'</span><span class="token punctuation">,</span> 
            <span class="token string single-quoted-string">'sl.id as site_location_id'</span><span class="token punctuation">,</span> 
            <span class="token string single-quoted-string">'cs.id as company_site_id'</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">'cp.name as company_name'</span><span class="token punctuation">,</span> 
            <span class="token string single-quoted-string">'sl.name as site_location_name'</span><span class="token punctuation">,</span> 
            <span class="token string single-quoted-string">'cs.name as company_site_name'</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">'cs.city as company_site_city'</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">'sp.base_price as base_price'</span><span class="token punctuation">,</span> 
            <span class="token string single-quoted-string">'sp.price as price'</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">)</span>
        <span class="token operator">-></span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Company'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'cp.id = cs.company_id'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'cp'</span><span class="token punctuation">)</span>
        <span class="token operator">-></span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'ShippingPrice'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'sp.company_site_id = cs.id'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'sp'</span><span class="token punctuation">)</span>
        <span class="token operator">-></span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'SiteLocation'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'sp.site_location_id = sl.id'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'sl'</span><span class="token punctuation">)</span>
        <span class="token operator">-></span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'cs.active = 1 '</span><span class="token operator">.</span>
                <span class="token string single-quoted-string">'AND sl.active = 1 '</span><span class="token operator">.</span> <span class="token comment">// or ->andWhere('condition2')</span>
                <span class="token string single-quoted-string">'AND sp.active = 1 '</span><span class="token operator">.</span>
                <span class="token string single-quoted-string">'AND cp.active = 1'</span><span class="token punctuation">)</span>
        <span class="token operator">-></span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'cp.name, sl.name, cs.name'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$result</span> <span class="token operator">=</span> <span class="token variable">$qb</span><span class="token operator">-></span><span class="token function">getQuery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-></span><span class="token function">execute</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-></span><span class="token function">toArray</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="apicore" tabindex="-1"><a class="header-anchor" href="#apicore" aria-hidden="true">#</a> ApiCore</h2>
<h3 id="constant-definitions" tabindex="-1"><a class="header-anchor" href="#constant-definitions" aria-hidden="true">#</a> Constant definitions</h3>
<p>APP_PATH and BASE_PATH in the <code v-pre>index.php</code> :</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token function">define</span><span class="token punctuation">(</span><span class="token constant">BASE_PATH</span><span class="token punctuation">,</span> <span class="token constant">__DIR__</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">define</span><span class="token punctuation">(</span><span class="token constant">APP_PATH</span><span class="token punctuation">,</span> <span class="token constant">BASE_PATH</span> <span class="token operator">.</span> <span class="token string single-quoted-string">'/src/'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="configuration" tabindex="-1"><a class="header-anchor" href="#configuration" aria-hidden="true">#</a> Configuration</h3>
<p>Config like this <code v-pre>src/config/config.php</code> :</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">'database'</span> <span class="token operator">=></span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">'adapter'</span>   <span class="token operator">=></span> <span class="token string single-quoted-string">'MySql'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'host'</span>      <span class="token operator">=></span> <span class="token string single-quoted-string">'localhost'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'username'</span>  <span class="token operator">=></span> <span class="token string single-quoted-string">'dbuser'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'password'</span>  <span class="token operator">=></span> <span class="token string single-quoted-string">'dbpass'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'dbname'</span>    <span class="token operator">=></span> <span class="token string single-quoted-string">'phalcondb'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'charset'</span>   <span class="token operator">=></span> <span class="token string single-quoted-string">'utf8mb4'</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">'appliation'</span>    <span class="token operator">=></span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">'apiKey'</span>    <span class="token operator">=></span> <span class="token string single-quoted-string">'sdfjaksldjfalksjdfLKJKLJLSJFDLFKJ8878-kldsfkljsdflkj'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'modelsDir'</span>      <span class="token operator">=></span> <span class="token string single-quoted-string">'/Models'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'controllersDir'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'/Controllers'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'viewsDir'</span>       <span class="token operator">=></span> <span class="token string single-quoted-string">'/Views'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'servicesDir'</span>    <span class="token operator">=></span> <span class="token string single-quoted-string">'/Services'</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">'tasksDir'</span>       <span class="token operator">=></span> <span class="token string single-quoted-string">'/Tasks'</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="routes" tabindex="-1"><a class="header-anchor" href="#routes" aria-hidden="true">#</a> Routes</h3>
<p>Routes in <code v-pre>src/config/router.php</code> :</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token variable">$collection</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">Phalcon<span class="token punctuation">\</span>Mvc<span class="token punctuation">\</span>Micro<span class="token punctuation">\</span>Collection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$collection</span><span class="token operator">-></span><span class="token function">setHandler</span><span class="token punctuation">(</span><span class="token class-name static-context">SiteController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span>
           <span class="token operator">-></span><span class="token function">setPrefix</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'/site'</span><span class="token punctuation">)</span>
           <span class="token operator">-></span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'/'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'indexAction'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$app</span><span class="token operator">-></span><span class="token function">mount</span><span class="token punctuation">(</span><span class="token variable">$collection</span><span class="token punctuation">)</span><span class="token punctuation">;</span>           
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="preflight-responses" tabindex="-1"><a class="header-anchor" href="#preflight-responses" aria-hidden="true">#</a> Preflight responses</h3>
<p>Add preflight responses in <code v-pre>src/Controllers/BaseController.php</code>:</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token doc-comment comment">/**
  * Provides a base CORS policy for routes like '/users' that represent a Resource's base url
  * Origin is allowed from all urls.  Setting it here using the Origin header from the request
  * allows multiple Origins to be served.  It is done this way instead of with a wildcard '*'
  * because wildcard requests are not supported when a request needs credentials.
  *
  * <span class="token keyword">@return</span> <span class="token class-name"><span class="token keyword">true</span></span>
  */</span>
 <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">optionsBase</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">{</span>
  <span class="token variable">$response</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token property">di</span><span class="token operator">-></span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'response'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Allow-Methods'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'GET, POST, OPTIONS, HEAD'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Allow-Origin'</span><span class="token punctuation">,</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token property">di</span><span class="token operator">-></span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'request'</span><span class="token punctuation">)</span><span class="token operator">-></span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Origin'</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Allow-Credentials'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'true'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Allow-Headers'</span><span class="token punctuation">,</span> <span class="token string double-quoted-string">"origin, x-requested-with, content-type"</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Max-Age'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'86400'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
 <span class="token punctuation">}</span>

 <span class="token doc-comment comment">/**
  * Provides a CORS policy for routes like '/users/123' that represent a specific resource
  *
  * <span class="token keyword">@return</span> <span class="token class-name"><span class="token keyword">true</span></span>
  */</span>
 <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">optionsOne</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">{</span>
  <span class="token variable">$response</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token property">di</span><span class="token operator">-></span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'response'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Allow-Methods'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'GET, PUT, PATCH, DELETE, OPTIONS, HEAD'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Allow-Origin'</span><span class="token punctuation">,</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token property">di</span><span class="token operator">-></span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'request'</span><span class="token punctuation">)</span><span class="token operator">-></span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Origin'</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Allow-Credentials'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'true'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Allow-Headers'</span><span class="token punctuation">,</span> <span class="token string double-quoted-string">"origin, x-requested-with, content-type"</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token variable">$response</span><span class="token operator">-></span><span class="token function">setHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Access-Control-Max-Age'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'86400'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
 <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="core-class" tabindex="-1"><a class="header-anchor" href="#core-class" aria-hidden="true">#</a> Core class</h3>
<p>And finally the <code v-pre>ApiCore</code> class:</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">namespace</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Core<span class="token punctuation">\</span>ApplicationFactory</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Exception</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Config</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Loader</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Mvc<span class="token punctuation">\</span>Micro</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Url</span> <span class="token keyword">as</span> UrlResolver<span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Config<span class="token punctuation">\</span>Adapter<span class="token punctuation">\</span>Php</span> <span class="token keyword">as</span> PhpConfig<span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Mvc<span class="token punctuation">\</span>View<span class="token punctuation">\</span>Simple</span> <span class="token keyword">as</span> View<span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Di<span class="token punctuation">\</span>FactoryDefault</span> <span class="token keyword">as</span> DefaultDi<span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Events<span class="token punctuation">\</span>Manager</span> <span class="token keyword">as</span> EventsManager<span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Mvc<span class="token punctuation">\</span>Model<span class="token punctuation">\</span>Manager</span> <span class="token keyword">as</span> ModelsManager<span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Di<span class="token punctuation">\</span>FactoryDefault<span class="token punctuation">\</span>Cli</span> <span class="token keyword">as</span> CliDi<span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Phalcon<span class="token punctuation">\</span>Cli<span class="token punctuation">\</span>Console</span> <span class="token keyword">as</span> ConsoleApp<span class="token punctuation">;</span>

<span class="token doc-comment comment">/**
 * CLI and REST API application factory.
 *
 * For CLI use createCLI() and use createMicro() for REST API services.
 *
 * Config files: APP_PATH/config/config.php and APP_PATH/config/router.php
 */</span>
<span class="token keyword">class</span> <span class="token class-name-definition class-name">ApiCore</span>
<span class="token punctuation">{</span>
    <span class="token doc-comment comment">/**
     * Creates a Phalcon Micro application
     *
     * <span class="token keyword">@return</span> <span class="token class-name">Micro</span>
     * <span class="token keyword">@throws</span> <span class="token class-name">Exception</span>
     */</span>
    <span class="token keyword">static</span> <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">createMicro</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
