                <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$hasConfKey</span> <span class="token operator">&amp;&amp;</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$req</span><span class="token operator">-></span><span class="token function">hasHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'X-API-Key'</span><span class="token punctuation">)</span> <span class="token operator">||</span> <span class="token punctuation">(</span><span class="token variable">$req</span><span class="token operator">-></span><span class="token function">getHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'X-API-Key'</span><span class="token punctuation">)</span> <span class="token operator">!==</span> <span class="token variable">$confArray</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'apiKey'</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    <span class="token variable">$app</span><span class="token operator">-></span><span class="token property">response</span><span class="token operator">-></span><span class="token function">setJsonContent</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
                        <span class="token string single-quoted-string">'status'</span>  <span class="token operator">=></span> <span class="token string single-quoted-string">'ERROR'</span><span class="token punctuation">,</span>
                        <span class="token string single-quoted-string">'message'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'Unauthorized'</span><span class="token punctuation">,</span>
