                <span class="token variable">$app</span><span class="token operator">-></span><span class="token property">response</span><span class="token operator">-></span><span class="token function">setStatusCode</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">,</span> <span class="token string double-quoted-string">"Not Found"</span><span class="token punctuation">)</span>
