            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\</span>Phalcon<span class="token punctuation">\</span>Exception</span><span class="token punctuation">(</span><span class="token string double-quoted-string">"Router definition not found!"</span><span class="token punctuation">,</span> <span class="token number">500</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
