    <span class="token keyword">static</span> <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">createCLI</span><span class="token punctuation">(</span><span class="token variable">$appPath</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span><span class="token variable">$argv</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$di</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">CliDi</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">initServices</span><span class="token punctuation">(</span><span class="token variable">$di</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">initLoader</span><span class="token punctuation">(</span><span class="token variable">$di</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$console</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ConsoleApp</span><span class="token punctuation">(</span><span class="token variable">$di</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$arguments</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

